x","inline":true,"children":[{"text":"ex"}]},{"text":"."}]}],"id":"3bb5ae80-7026-422c-a6ee-ec453335a217"},"multimedia":{"plugin":"image","state":{"src":"","caption":{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"b9618e68-e122-4a4f-b9bc-35f7baacace6"}},"id":"f0431c3d-e0c8-4d75-b075-a5db6240b128"},"illustrating":true,"width":50},"id":"1f29ee07-f626-49ec-8aef-bb6add4a87dc"},"content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"In einem entsprechenden Computerprogramm realisierst du eine Iteration durch eine While-Schleife. Innerhalb der While-Schleife wird eine Berechnung solange wiederholt, wie die Schleifenbedingung erfüllt ist. Aber wie entwirfst du eine While-Schleife?"}]},{"type":"p","children":[{"text":""}]},{"type":"h","level":3,"children":[{"text":"Iterationsschema"}]},{"type":"p","children":[{"text":"Um das Ganze systematisch anzugehen, stellst du als Erstes ein "},{"text":"Iterationsschema","strong":true},{"text":" auf. Wenn du zum Beispiel "},{"type":"math","src":"a^n","inline":true,"children":[{"text":"an"}]},{"text":" berechnen willst, sieht das Iterationsschema folgendermaßen aus: "}]},{"type":"p","children":[{"text":""}]}],"id":"c666a449-2be8-4522-9b56-780de858c664"},{"plugin":"image","state":{"src":"https://assets.serlo.org/583c2e90-903c-11ed-9c37-8b1e198c6fe6/image.png","caption":{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"349fd160-7265-4930-ad3e-0e3cb579b042"}},"id":"9632bc8a-2aba-4234-a072-4803b9fb3659"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Du brauchst zwei Variablen, deren Werte sich verändern: "},{"type":"math","src":"i","inline":true,"children":[{"text":"i"}]},{"text":" und "},{"type":"math","src":"p","inline":true,"children":[{"text":"p"}]},{"text":". Für diese legst du jeweils eine Zeile in dem Iterationsschema an. Mit der Variablen "},{"type":"math","src":"i","inline":true,"children":[{"text":"i"}]},{"text":" zählst du die Iterationen und mit der Variablen "},{"type":"math","src":"p","inline":true,"children":[{"text":"p"}]},{"text":" merkst du dir das jeweilige Zwischenergebnis "},{"type":"math","src":"a^i","inline":true,"children":[{"text":"ai"}]},{"text":". Die Werte der Variablen "},{"type":"math","src":"a","inline":true,"children":[{"text":"a"}]},{"text":" und "},{"type":"math","src":"n","inline":true,"children":[{"text":"n"}]},{"text":" verändern sich dagegen nicht."}]},{"type":"p","children":[{"text":""}]},{"type":"h","level":3,"children":[{"text":"Iterationsgleichungen aufstellen"}]},{"type":"p","children":[{"text":"Nun schaust du, wie jeweils der Wert "},{"type":"math","src":"v","inline":true,"children":[{"text":"v"}]},{"text":" einer Variablen aus dem vorher berechneten Wert "},{"type":"math","src":"v'","inline":true,"children":[{"text":"v'"}]},{"text":" hervorgeht:"}]},{"type":"math","src":"i = i' + 1","inline":false,"children":[{"text":""}]},{"type":"math","src":"p = p' \cdot a","inline":false,"children":[{"text":""}]},{"type":"p","children":[{"text":"Der Wert einer Variablen "mit Strich" bezeichnet dabei immer den Wert der Variablen in der vorherigen Spalte."}]},{"type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":"Du berechnest also den Wert von "},{"type":"math","src":"i","inline":true,"children":[{"text":"i"}]},{"text":" in jeder Spalte, indem du den Wert von "},{"type":"math","src":"i","inline":true,"children":[{"text":"i"}]},{"text":" aus der vorherigen Spalte nimmst und 1 hinzu addierst. Und den Wert von "},{"type":"math","src":"p","inline":true,"children":[{"text":"p"}]},{"text":" in jeder Spalte berechnest du, indem du den Wert von "},{"type":"math","src":"p","inline":true,"children":[{"text":"p"}]},{"text":" aus der vorherigen Spalte mit "},{"type":"math","src":"a","inline":true,"children":[{"text":"a"}]},{"text":" multiplizierst."}]},{"type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":"In der ersten Spalte, die keine vorherige Spalte hat, werden die Werte der Variablen durch Initialisierung festgelegt. "}]},{"type":"math","src":"i = 0","inline":false,"children":[{"text":""}]},{"type":"math","src":"p = 1","inline":false,"children":[{"text":""}]}],"id":"80540d49-135a-40bd-b250-93c0ff2d2f54"},{"plugin":"text","state":[{"type":"h","level":3,"children":[{"text":"Iterationsgleichungen in ein While-Programm umsetzen"}]},{"type":"p","children":[{"text":"Ohne viel nachzudenken, setzt du die Iterationsgleichungen gleichsam mechanisch in ein While-Programm um. Du beginnst mit den Initialisierungen. Dann schreibst du die While-Schleife. Der Schleifenkörper besteht aus den Iterationsgleichungen."}]}],"id":"96a6731c-4b64-47dd-9bc0-d685b5570a26"},{"plugin":"highlight","state":{"code":"i=0;
p=1;
while (i<n)
{
    i=i+1;
    p=p*a;
}","language":"java","showLineNumbers":false},"id":"f7489a33-2e51-40b5-81f6-637257c39711"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Als Schleifen­bedingung wählst du eine Bedingung, die im Iterations­schema für alle Spalten "},{"text":"vor ","em":true},{"text":"der Spalte gilt, in der du das Ergebnis der Berechnung erwartest."}]},{"type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":"Fertig! Vorausgesetzt ist, dass du alle Variablen deklariert hast und dass du die Variablen "},{"type":"math","src":"a","inline":true,"children":[{"text":"a"}]},{"text":" und "},{"type":"math","src":"n","inline":true,"children":[{"text":"n"}]},{"text":" mit Werten versehen hast."}]},{"type":"p","children":[{"text":""}]},{"type":"h","level":2,"children":[{"text":"Vorteile des Iterationsschemas"}]},{"type":"p","children":[{"text":"Lohnt sich der ganze Aufwand? Ja, definitiv! Auch bei dem hier gezeigten einfachsten Beispiel kannst du dich anhand des Iterationsschemas davon überzeugen, ob dein Programm korrekt ist, insbesondere"}]},{"type":"unordered-list","children":[{"type":"list-item","children":[{"type":"list-item-child","children":[{"text":"ob die Initialisierungen stimmen,"}]}]},{"type":"list-item","children":[{"type":"list-item-child","children":[{"text":"ob die Schleifenbedingung richtig ist,"}]}]},{"type":"list-item","children":[{"type":"list-item-child","children":[{"text":"ob im Schleifenkörper die richtigen Anweisungen in der richtigen Reihenfolge stehen."}]}]}]},{"type":"p","children":[{"text":"Und erst recht lohnt es sich, mithilfe eines Iterationsschemas systematisch vorzugehen, wenn die Berechnung komplizierter ist. Schau dir einmal die Aufgaben an."}]},{"type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":"Sicherlich kriegst du es auch hin, die Lösungen sozusagen freihändig zu programmieren, aber mit einem Iterationsschema hast du jederzeit eine Referenz, mit der du die Korrektheit deines Programms nachvollziehen kannst."}]}],"id":"4a11f5d8-b1c8-4364-840e-8a90ba1516a0"}],"id":"5716b0b5-a2ab-44ac-bcba-5931d793ffae"},"exercises":[{"plugin":"injection","state":"/265530","id":"6a165c43-3886-43e4-ae8c-a2cb3059c156"},{"plugin":"injection","state":"/265538","id":"1cb468c2-19b1-4efa-a8ec-ef221d79ade6"}],"exerciseFolder":{"id":"","title":""},"relatedContent":{"articles":[],"courses":[],"videos":[]},"sources":[]},"id":"3ff2749a-e269-418b-96b5-c9110aae3ee1"}}
